import {describe,it,expect} from 'vitest'
import {compositeRgba8,sourceRgba8SeparableChannel,sourceRgba8CompositeModeId,SOURCE_RGBA8_GENERIC_SC_PROFILE as profile} from './sourceColorRgba8'
// Authored U8 examples, independently reduced from pinned native functors.
// No output here is claimed to have been generated by an executed native oracle.
const cases=[['equivalence',128,160,128],['additiveSubtractive',94,143,117],['arcTangent',52,122,102],['negation',254,223,170],['inverseSubtract',1,96,85],['grainMerge',129,160,129],['grainExtract',255,224,170],['allanon',127,159,128],['geometricMean',111,151,122],['parallel',95,143,117]] as const
const oldIds=['over','add','alphaDarken','multiply','lighten','colorDodge','overlay','darken','screen','colorBurn','linearBurn','subtract','difference','exclusion','softLight','hardLight','divide','linearLight','vividLight','pinLight','hardMix','darkerColor','lighterColor','hue','saturation','luminosity','hardMixPhotoshop','softLightSvg'] as const
describe('browser functional channel extension, pinned U8 graph',()=>{
 it('preserves every published mode ID and appends ten new IDs',()=>{oldIds.forEach((mode,id)=>expect(sourceRgba8CompositeModeId(mode)).toBe(id));cases.forEach(([mode],i)=>expect(sourceRgba8CompositeModeId(mode)).toBe(28+i))})
 for(const [mode,opaque,masked,partial]of cases)it(mode+' opaque and independently reduced half-mask blend',()=>{
  expect(sourceRgba8SeparableChannel(mode,64,192)).toBe(opaque)
  expect(compositeRgba8([64,64,64,255],[192,192,192,255],{mode,profile,opacity:1})).toEqual([opaque,opaque,opaque,255])
  expect(compositeRgba8([64,64,64,255],[192,192,192,255],{mode,profile,opacity:1,mask:128})).toEqual([masked,masked,masked,255])
  expect(compositeRgba8([64,64,64,128],[192,192,192,128],{mode,profile,opacity:1})).toEqual([partial,partial,partial,192])
  expect(compositeRgba8([64,64,64,255],[192,192,192,255],{mode,profile,opacity:0})).toEqual([192,192,192,255])
  expect(compositeRgba8([64,64,64,0],[192,192,192,97],{mode,profile,opacity:1})).toEqual([192,192,192,97])
  expect(compositeRgba8([64,64,64,255],[192,192,192,0],{mode,profile,opacity:1,mask:128})).toEqual([64,64,64,128])
 })
 it('retains native integer half, reciprocal staging, argument orientation and native equivalence semantics',()=>{
  expect(sourceRgba8SeparableChannel('allanon',255,255)).toBe(254)
  expect(sourceRgba8SeparableChannel('allanon',1,1)).toBe(0)
  expect(sourceRgba8SeparableChannel('grainMerge',0,255)).toBe(128)
  expect(sourceRgba8SeparableChannel('grainExtract',255,0)).toBe(0)
  expect(sourceRgba8SeparableChannel('equivalence',73,73)).toBe(0)
  for(const [s,d,expected]of [[0,0,0],[0,255,0],[255,0,255],[255,255,128]] as const)expect(sourceRgba8SeparableChannel('arcTangent',s,d)).toBe(expected)
  expect(sourceRgba8SeparableChannel('parallel',0,255)).toBe(0)
  expect(sourceRgba8SeparableChannel('parallel',255,255)).toBe(255)
  expect(sourceRgba8SeparableChannel('geometricMean',255,255)).toBe(255)
 })
})
